INSERT INTO TB_TEST_RESULT (
    , REG_DTM
) VALUES (
    #{serial}, #{stepCd}, #{startDtm}, #{endDtm}, #{workDt}, #{lotId}, #{prodCd}, #{testerId}, #{operNm}, #{resultCd},
