mapper.update:
UPDATE TB_TEST_RESULT
   SET END_DTM     = #{endDtm}
     , WORK_DT     = #{workDt}
     , LOT_ID      = #{lotId}
     , PROD_CD     = #{prodCd}
     , TESTER_ID   = #{testerId}
     , OPER_NM     = #{operNm}
     , RESULT_CD   = #{resultCd}
     , READ_MBPS   = #{readMbps}
     , WRITE_MBPS  = #{writeMbps}
     , LAT_US      = #{latUs}
     , BAD_BLK     = #{badBlk}
     , ECC_CNT     = #{eccCnt}
     , MAX_TEMP_C  = #{maxTempC}
     , FW_VER      = #{fwVer}
     , VENDOR_CD   = #{vendorCd}
     , SRC_FILE_NM = #{srcFileNm}
     , UPD_DTM     = SYSDATE
 WHERE SERIAL    = #{serial}
   AND STEP_CD   = #{stepCd}
   AND START_DTM = #{startDtm}

mapper.select:
SELECT COUNT(*)
  FROM TB_TEST_RESULT
 WHERE SERIAL    = #{serial}
   AND STEP_CD   = #{stepCd}
   AND START_DTM = #{startDtm}

SELECT SERIAL
  FROM (
        SELECT ROWNUM AS RNUM, A.SERIAL
          FROM (
                SELECT DISTINCT SERIAL
                  FROM TB_TEST_RESULT
                 WHERE WORK_DT = #{workDt}
                 ORDER BY SERIAL
               ) A
         WHERE ROWNUM <= #{_skiprows} + #{_pagesize}
       )
 WHERE RNUM > #{_skiprows}

SELECT 
  FROM TB_TEST_RESULT
 WHERE SERIAL  = #{serial}
   AND WORK_DT = #{workDt}
 ORDER BY STEP_CD, START_DTM
